INSERT INTO zhishi_notices (id, real, source, publish_date, title, event, audience, deadline, countdown, materials, entry, confidence, priority, points, digest_one, digest_points, raw, url, site, unit, src_generated_at) VALUES ('ahau-028', TRUE, '安徽农业大学官网', NULL, '【追梦安农人㊷】周杰：四十年，把忠诚写在立德树人一线', '校内通知', NULL, '2026-11-03', NULL, NULL, NULL, 0.5, 'medium', '[{"text": "【追梦安农人㊷】周杰：四十年，把忠诚写在立德树人一线 【 发布日期：2026-11-03 】 【 来", "quote": "【追梦安农人㊷】周杰：四十年，把忠诚写在立德树人一线 【 发布日期：2026-11-03 】 【 来"}]'::jsonb, '校内通知：【追梦安农人㊷】周杰：四十年，把忠诚写在立德树人一线', '[{"text": "【追梦安农人㊷】周杰：四十年，把忠诚写在立德树人一线 【 发布日期：2026-11-03 】 【 来", "quote": "【追梦安农人㊷】周杰：四十年，把忠诚写在立德树人一线 【 发布日期：2026-11-03 】 【 来"}]'::jsonb, '【追梦安农人㊷】周杰：四十年，把忠诚写在立德树人一线 【 发布日期：2026-11-03 】 【 来源：宣传部 】 【 点击数： 】 “忠诚党的教育事业”，八个滚烫大字，镌刻在少年时的学生证上，也成为动物医学院周杰教授一生不变的人生信条。1987年，他怀揣纯粹的育人理想，踏上梦寐以求的三尺讲台，自此扎根在教育教学一线，一干便是四十载。从青涩从教的青年学子到深耕行业的资深教授，周杰始终笃信“教书先育人，育人先育心”，以初心守讲台、以匠心抓教改、以恒心伴成长，在平凡的杏坛默默耕耘，用坚守诠释一名教育工作者的质朴担当与追', 'http://news.ahau.edu.cn/info/1005/143327.htm', '安徽农业大学官网', 'www', '2026-11-04 13:33:17') ON CONFLICT (id) DO UPDATE SET source=EXCLUDED.source, publish_date=EXCLUDED.publish_date, title=EXCLUDED.title, event=EXCLUDED.event, deadline=EXCLUDED.deadline, points=EXCLUDED.points, digest_one=EXCLUDED.digest_one, digest_points=EXCLUDED.digest_points, raw=EXCLUDED.raw, url=EXCLUDED.url, site=EXCLUDED.site, unit=EXCLUDED.unit, src_generated_at=EXCLUDED.src_generated_at